(() => {
"use strict";
const style=document.createElement("style");
style.textContent=`
#noxSwarmOpen{border-color:#a18bff70;color:#e5deff}
#noxSwarmLayer{position:fixed;inset:0;z-index:1200;display:none;place-items:center;padding:clamp(8px,2vw,22px);background:#030712dc;backdrop-filter:blur(18px);overflow:auto;color:#e9f5ff;font:13px system-ui,sans-serif}
#noxSwarmLayer.open{display:grid}
.ns-shell{width:min(1180px,100%);max-height:96vh;overflow:auto;border:1px solid #8c7cff44;border-radius:20px;background:radial-gradient(ellipse at 50% 0%,#182647,#080e1a 65%);box-shadow:0 20px 80px #0008}
.ns-head{display:flex;align-items:center;gap:12px;padding:14px 18px;border-bottom:1px solid #86dfff22;position:sticky;top:0;background:#091321ed;backdrop-filter:blur(16px);z-index:3}
.ns-head strong{letter-spacing:.15em}.ns-head small{color:#91a9c3;font:9px monospace;letter-spacing:.1em}.ns-spacer{flex:1}
.ns-btn{border:1px solid #82dfff36;background:#0c1a2b;color:#e7f6ff;border-radius:9px;padding:9px 12px;font-size:11px;cursor:pointer}
.ns-btn.primary{background:linear-gradient(135deg,#3b4e8e,#59418d);border-color:#b1a0ff66}.ns-btn:disabled{opacity:.45;cursor:not-allowed}
.ns-content{display:grid;grid-template-columns:minmax(0,1fr) 290px;gap:0}
.ns-main{min-width:0;padding:16px}.ns-side{padding:16px;border-left:1px solid #8cceee20;background:#06111e88;display:flex;flex-direction:column;gap:12px}
.ns-label{display:block;color:#8ca8c4;font:9px monospace;letter-spacing:.13em;margin:0 0 7px}
.ns-input{width:100%;background:#07101d;border:1px solid #75cfff35;border-radius:9px;padding:11px;color:#eef8ff;outline:none}.ns-input:focus{border-color:#a18bff}
.ns-stage{height:440px;position:relative;overflow:hidden;border:1px solid #7bdfff20;border-radius:14px;background:radial-gradient(ellipse at 50% 50%,#162e4b88,transparent 62%),linear-gradient(#07101a,#08111f)}
.ns-stage svg{position:absolute;inset:0;width:100%;height:100%;pointer-events:none}
.ns-link{stroke:#7ddfff58;stroke-width:1.6;stroke-dasharray:7 8;animation:nsFlow 4s linear infinite}
.ns-core{position:absolute;left:50%;top:50%;transform:translate(-50%,-50%);width:108px;height:108px;border-radius:50%;display:grid;place-items:center;text-align:center;border:1px solid #b3a0ffba;background:radial-gradient(circle,#5d55bd66,#111d37 66%,#0b1221);box-shadow:0 0 32px #7771ff44,inset 0 0 28px #6f7cff22;z-index:1}
.ns-core:before,.ns-core:after{content:"";position:absolute;inset:-11px;border:1px solid #76eaff55;border-radius:50%;transform:rotate(-20deg) scaleY(.36);animation:nsOrbit 7s linear infinite}
.ns-core:after{inset:-19px;border-color:#a18bff55;transform:rotate(58deg) scaleY(.42);animation-duration:11s}
.ns-core b{font-size:15px;letter-spacing:.2em}.ns-core small{font:8px monospace;color:#a6b5d2;margin-top:4px}
.ns-node{position:absolute;width:clamp(104px,18%,168px);min-height:62px;transform:translate(-50%,-50%);border:1px solid #6fcffb45;border-radius:10px;padding:9px;background:#091827ef;box-shadow:0 8px 22px #0004;z-index:2;overflow-wrap:anywhere}
.ns-node strong{display:block;font-size:10px;color:#c9f4ff;margin-bottom:4px}.ns-node span{display:block;font-size:10px;color:#a9bed0;line-height:1.35}.ns-node em{display:inline-block;margin-top:6px;font:8px monospace;color:#8ce8c4;text-transform:uppercase;font-style:normal}
.ns-node.running{border-color:#6de8ff9c;box-shadow:0 0 18px #43d9ff20}.ns-node.failed{border-color:#ff7f9b9c}.ns-node.completed{border-color:#78f0c277;opacity:.82}.ns-node.queued{border-color:#8e9db855}
.ns-empty{position:absolute;left:50%;bottom:13px;transform:translateX(-50%);font:9px monospace;color:#7894b2;text-align:center;width:90%}
.ns-section{border:1px solid #76d7f020;border-radius:11px;padding:12px;background:#07142188}.ns-status{font-size:11px;color:#b8cce0;line-height:1.55}.ns-events{max-height:190px;overflow:auto;display:flex;flex-direction:column;gap:8px}.ns-event{border-left:2px solid #79dfff55;padding:4px 8px;color:#9db4c9;font-size:10px;line-height:1.45}.ns-event.warning{border-color:#ffbe69;color:#eac7a3}
.ns-agent-list{display:flex;flex-direction:column;gap:6px}.ns-agent-row{display:flex;justify-content:space-between;gap:8px;border-bottom:1px solid #9bdcf00f;padding:6px 0;font-size:10px}.ns-agent-row span:last-child{color:#8cdff3;text-transform:uppercase;font:9px monospace}
.ns-note{font-size:10px;line-height:1.55;color:#7893ad}.ns-actions{display:flex;gap:7px;flex-wrap:wrap}
@keyframes nsFlow{to{stroke-dashoffset:-60}}@keyframes nsOrbit{to{rotate:360deg}}
@media(prefers-reduced-motion:reduce){.ns-link,.ns-core:before,.ns-core:after{animation:none}}
@media(max-width:780px){.ns-content{grid-template-columns:1fr}.ns-side{border-left:0;border-top:1px solid #8cceee20}.ns-stage{height:400px}.ns-node{width:clamp(91px,25%,140px);padding:7px}.ns-node span{font-size:9px}.ns-core{width:80px;height:80px}.ns-head small{display:none}}
@media(max-width:430px){.ns-stage{height:350px}.ns-node{width:108px}.ns-core{width:66px;height:66px}.ns-core b{font-size:11px}.ns-node strong{font-size:9px}}
`;
document.head.appendChild(style);
const open=document.createElement("button");open.id="noxSwarmOpen";open.className="iconbtn";open.textContent="✣ AGENT SWARM";open.setAttribute("aria-haspopup","dialog");
const top=document.querySelector(".topright");if(top)top.insertBefore(open,top.firstChild);
const layer=document.createElement("div");layer.id="noxSwarmLayer";layer.setAttribute("role","dialog");layer.setAttribute("aria-modal","true");layer.setAttribute("aria-label","NOX autonomous agent swarm");
layer.innerHTML=`<div class="ns-shell"><header class="ns-head"><strong>NOX <span style="color:#a18bff">AGENT SWARM</span></strong><small>MASTER ORCHESTRATOR · SPECIALIST NODES</small><span class="ns-spacer"></span><button class="ns-btn" id="nsClose">✕ Close</button></header><div class="ns-content"><main class="ns-main"><label class="ns-label" for="nsGoal">COMPLEX TASK / DESIRED OUTCOME</label><textarea class="ns-input" id="nsGoal" rows="3" maxlength="6000" placeholder="Plan a secure login and responsive dashboard, including API contracts and tests…"></textarea><div class="ns-actions" style="margin:9px 0 13px"><button class="ns-btn primary" id="nsLaunch">✣ Launch swarm</button><button class="ns-btn" id="nsCancel" disabled>Stop all agents</button><button class="ns-btn" id="nsRefresh">Refresh state</button><select class="ns-btn" id="nsHistory" aria-label="Select a previous swarm job" title="Browse saved swarm jobs"><option value="">Job history…</option></select><button class="ns-btn" id="nsHistoryRefresh">↻ History</button><button class="ns-btn" id="nsExport" disabled>⇩ Export report</button></div><div class="ns-stage" id="nsStage"><svg viewBox="0 0 1000 600" preserveAspectRatio="none" aria-hidden="true"><line class="ns-link" x1="500" y1="300" x2="180" y2="110"/><line class="ns-link" x1="500" y1="300" x2="500" y2="85"/><line class="ns-link" x1="500" y1="300" x2="820" y2="110"/><line class="ns-link" x1="500" y1="300" x2="180" y2="490"/><line class="ns-link" x1="500" y1="300" x2="500" y2="520"/><line class="ns-link" x1="500" y1="300" x2="820" y2="490"/></svg><div class="ns-core"><div><b>NOX</b><small>ORCHESTRATOR</small></div></div><div class="ns-empty" id="nsEmpty">The core is ready. Launch a task to spawn real backend agent nodes.</div><div id="nsNodes"></div></div><p class="ns-note" style="margin-top:9px">Nodes reflect backend task states, not decorative progress. Progress is shown only when the backend reports a measurable value. This hosted swarm reasons and produces text artifacts; it does not directly edit repository files, run shell commands, deploy, or generate media.</p></main><aside class="ns-side"><section class="ns-section"><label class="ns-label">JOB STATUS</label><div class="ns-status" id="nsStatus" aria-live="polite">No swarm job selected.</div><div class="ns-status" id="nsJobMeta" style="margin-top:7px;color:#7894ad"></div></section><section class="ns-section"><label class="ns-label">SPECIALIST ROSTER</label><div class="ns-agent-list" id="nsRoster"><div class="ns-status">No agents spawned yet.</div></div></section><section class="ns-section"><label class="ns-label">LIVE EVENT LOG</label><div class="ns-events" id="nsEvents"><div class="ns-event">Awaiting an actual backend event.</div></div></section><section class="ns-section"><label class="ns-label">UNIFIED RESULT</label><div class="ns-status" id="nsResult">No result yet.</div></section><p class="ns-note">Requires a server-side OPENROUTER_API_KEY and provider quota. Max concurrency and task count are bounded server-side. Cancel stops unfinished in-process work; a server restart marks interrupted jobs failed rather than pretending they resumed.</p></aside></div></div>`;
document.body.appendChild(layer);
const $=id=>document.getElementById(id);
let currentId=null,timer=null,loading=false,lastJob=null;
const escStatus=s=>String(s||"").replace(/_/g," ");
function setStatus(s){$("nsStatus").textContent=s}
function nodePositions(i,n){const positions=[[18,18],[50,14],[82,18],[18,81],[50,87],[82,81]];return positions[i%positions.length]}
function updateHistoryOption(job){const select=$("nsHistory");const option=[...select.options].find(item=>item.value===job.id);if(option){const goal=String(job.goal||"Swarm job").replace(/\s+/g," ").slice(0,54);option.textContent=goal+" · "+escStatus(job.status);}}
function render(job){
 if(!job)return;lastJob=job;currentId=job.id;$("nsExport").disabled=false;updateHistoryOption(job);if($("nsHistory").querySelector('option[value="'+job.id+'"]'))$("nsHistory").value=job.id;
 setStatus("Status: "+escStatus(job.status)+((job.error)?" — "+job.error:""));
 $("nsJobMeta").textContent="Job "+job.id.slice(0,10)+" · updated "+(job.updated_at||"—");
 $("nsCancel").disabled=["completed","failed","cancelled"].includes(job.status);
 $("nsLaunch").disabled=["planning","running","reviewing","queued"].includes(job.status);
 $("nsResult").textContent=job.result|| (job.status==="failed"?"No unified result. Specialist artifacts remain in job details.":"Waiting for all required specialist artifacts.");
 const nodes=$("nsNodes"),roster=$("nsRoster");nodes.replaceChildren();roster.replaceChildren();
 const agents=job.agents||[];
 if(!agents.length){$("nsEmpty").style.display="block";$("nsEmpty").textContent=job.status==="planning"?"Master orchestrator is validating a dependency graph…":"Planner has not produced agent contracts yet."}
 else{$("nsEmpty").style.display="none"}
 const labels={"architect":"ARCHITECT","frontend":"FRONTEND","backend":"BACKEND","coding":"CODING","alignment":"ALIGNMENT","integration":"INTEGRATION","debugging":"DEBUGGING","qa":"TESTING / QA","security":"SECURITY","research":"RESEARCH","analysis":"DATA ANALYSIS","fact_check":"FACT CHECK","creative":"CREATIVE","documentation":"DOCUMENTATION","general":"SPECIALIST"};
 agents.forEach((a,i)=>{const pos=nodePositions(i,agents.length),node=document.createElement("div");node.className="ns-node "+(a.status||"queued");node.style.left=pos[0]+"%";node.style.top=pos[1]+"%";const title=document.createElement("strong");title.textContent=labels[a.role]||String(a.role||"SPECIALIST").toUpperCase();const desc=document.createElement("span");desc.textContent=a.title||"Assigned task";const state=document.createElement("em");state.textContent=escStatus(a.status||"queued")+(Number.isFinite(a.progress)?" · "+a.progress+"%":"");node.append(title,desc,state);if(a.error){const err=document.createElement("span");err.textContent=a.error;node.append(err)}nodes.append(node);
 const row=document.createElement("div");row.className="ns-agent-row";const name=document.createElement("span");name.textContent=(labels[a.role]||a.role)+": "+(a.title||"");const stat=document.createElement("span");stat.textContent=escStatus(a.status);row.append(name,stat);roster.append(row)});
 const events=$("nsEvents");events.replaceChildren();(job.events||[]).slice(-24).reverse().forEach(e=>{const el=document.createElement("div");el.className="ns-event "+(e.level==="warning"?"warning":"");el.textContent=(e.at?new Date(e.at).toLocaleTimeString()+" · ":"")+e.message;events.append(el)});if(!(job.events||[]).length){const el=document.createElement("div");el.className="ns-event";el.textContent="No events yet.";events.append(el)}
}
function markdownSafe(value){return String(value??"").replace(/\r\n?/g,"\n").trim()}
function exportReport(){
 if(!lastJob){setStatus("Select a swarm job before exporting.");return}
 const job=lastJob,agents=Array.isArray(job.agents)?job.agents:[],events=Array.isArray(job.events)?job.events:[];
 const lines=["# NOX Agent Swarm Report","","- **Job ID:** "+markdownSafe(job.id),"- **Status:** "+markdownSafe(job.status),"- **Created:** "+markdownSafe(job.created_at||"Unknown"),"- **Updated:** "+markdownSafe(job.updated_at||"Unknown"),"","## Objective","",markdownSafe(job.goal)||"No objective recorded.","","## Unified result","",markdownSafe(job.result)||"No unified result was produced.","","## Specialist artifacts",""];
 if(!agents.length)lines.push("No specialist task contracts were saved.","");
 for(const agent of agents){
  lines.push("### "+markdownSafe(agent.title||agent.id||"Specialist task"),"","- **Role:** "+markdownSafe(agent.role||"unknown"),"- **Status:** "+markdownSafe(agent.status||"unknown"));
  if(agent.error)lines.push("- **Error:** "+markdownSafe(agent.error));
  lines.push("",markdownSafe(agent.result)||"No artifact returned.","");
 }
 lines.push("## Event log","");
 if(events.length){for(const event of events)lines.push("- "+markdownSafe(event.at||"Unknown time")+" — ["+markdownSafe(event.level||"info")+"] "+markdownSafe(event.message))}
 else lines.push("No events recorded.");
 lines.push("","---","Generated locally by the NOX Agent Swarm interface. This report reflects stored job data and does not independently verify claims inside agent artifacts.","");
 const blob=new Blob([lines.join("\n")],{type:"text/markdown;charset=utf-8"}),url=URL.createObjectURL(blob),link=document.createElement("a");
 link.href=url;link.download="nox-swarm-"+String(job.id||"report").slice(0,12)+".md";link.style.display="none";document.body.append(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);setStatus("Report exported locally as Markdown.");
}
async function ensureSession(){const r=await fetch("/api/session",{credentials:"same-origin",cache:"no-store"});if(!r.ok)throw Error("Could not initialize browser session (HTTP "+r.status+")")}
async function refresh(){if(!currentId)return;try{const r=await fetch("/api/swarm/jobs/"+encodeURIComponent(currentId),{credentials:"same-origin",cache:"no-store"});if(!r.ok)throw Error("Job status request failed (HTTP "+r.status+")");const d=await r.json();render(d.job);if(["completed","failed","cancelled"].includes(d.job.status)){if(timer){clearInterval(timer);timer=null}}}catch(e){setStatus("Status unavailable: "+e.message)}}
async function selectHistory(){const id=$("nsHistory").value;if(!id)return;currentId=id;if(timer){clearInterval(timer);timer=null}await refresh();if(lastJob&&["queued","planning","running","reviewing"].includes(lastJob.status))timer=setInterval(refresh,1800)}
async function loadHistory(preferredId){const select=$("nsHistory"),old=select.value;try{await ensureSession();const r=await fetch("/api/swarm/jobs?limit=20",{credentials:"same-origin",cache:"no-store"});if(!r.ok)throw Error("History request failed (HTTP "+r.status+")");const d=await r.json();select.replaceChildren();if(!d.jobs?.length){const empty=document.createElement("option");empty.value="";empty.textContent="No saved jobs yet";select.append(empty);return}for(const job of d.jobs){const option=document.createElement("option");option.value=job.id;const goal=String(job.goal||"Swarm job").replace(/\s+/g," ").slice(0,54);option.textContent=goal+" · "+escStatus(job.status);select.append(option)}const chosen=preferredId||currentId||old||d.jobs[0].id;select.value=d.jobs.some(job=>job.id===chosen)?chosen:d.jobs[0].id;await selectHistory()}catch(e){setStatus("Could not load job history: "+e.message)}}
async function launch(){if(loading)return;const goal=$("nsGoal").value.trim();if(goal.length<8){setStatus("Enter a task objective with at least 8 characters.");return}loading=true;$("nsLaunch").disabled=true;setStatus("Submitting objective to the backend orchestrator…");try{await ensureSession();const r=await fetch("/api/swarm/jobs",{method:"POST",credentials:"same-origin",headers:{"Content-Type":"application/json"},body:JSON.stringify({goal,language:"auto"})});const d=await r.json().catch(()=>({}));if(!r.ok)throw Error(d.detail||"Could not create swarm job (HTTP "+r.status+")");render(d.job);if(timer)clearInterval(timer);timer=setInterval(refresh,1800);await loadHistory(d.job.id);await refresh()}catch(e){setStatus("Could not start swarm: "+e.message);$("nsLaunch").disabled=false}finally{loading=false}}
async function cancel(){if(!currentId)return;const b=$("nsCancel");b.disabled=true;try{const r=await fetch("/api/swarm/jobs/"+encodeURIComponent(currentId)+"/cancel",{method:"POST",credentials:"same-origin"});const d=await r.json().catch(()=>({}));if(!r.ok)throw Error(d.detail||"Cancellation failed");render(d.job);if(timer){clearInterval(timer);timer=null}}catch(e){setStatus("Could not stop swarm: "+e.message);b.disabled=false}}
async function loadLatest(){await loadHistory(currentId||undefined)}
open.addEventListener("click",()=>{layer.classList.add("open");if(!lastJob)loadLatest()});$("nsClose").addEventListener("click",()=>layer.classList.remove("open"));layer.addEventListener("click",e=>{if(e.target===layer)layer.classList.remove("open")});document.addEventListener("keydown",e=>{if(e.key==="Escape")layer.classList.remove("open")});$("nsLaunch").addEventListener("click",launch);$("nsCancel").addEventListener("click",cancel);$("nsRefresh").addEventListener("click",refresh);$("nsHistory").addEventListener("change",selectHistory);$("nsHistoryRefresh").addEventListener("click",()=>loadHistory(currentId||undefined));$("nsExport").addEventListener("click",exportReport);
window.NOXAgentSwarm={open:()=>open.click(),refresh,activeJob:()=>currentId};
})();